// Reserves learn from expedition reports; no experience is generated by simply waiting.
let reserveVictoryContext=null;
const reserveAwardXp=awardXp;
awardXp=function(h,amount,...args){if(reserveVictoryContext&&h&&reserveVictoryContext.ids.has(h.id)&&Number.isFinite(amount)&&amount>0)reserveVictoryContext.total+=amount;return reserveAwardXp(h,amount,...args)};
const reserveWinBattle=winBattle;
winBattle=function(...args){const expedition=runState,battle=expedition?.battle;if(!battle)return reserveWinBattle(...args);const previous=reserveVictoryContext,context={ids:new Set(expedition.ids),total:0};reserveVictoryContext=context;let result;try{result=reserveWinBattle(...args)}finally{reserveVictoryContext=previous}if(runState!==expedition||expedition.battle||context.total<=0)return result;const share=context.total/Math.max(1,context.ids.size)*.2,recipients=heroes.filter(h=>!context.ids.has(h.id)&&!activeJobs.some(j=>j.heroIds.includes(h.id)));let awarded=0;for(const h of recipients){const accumulated=(Number(h.reserveXpFraction)||0)+share,whole=Math.floor(accumulated+1e-9);h.reserveXpFraction=Math.max(0,accumulated-whole);if(whole>0){reserveAwardXp(h,whole);awarded+=whole}}if(recipients.length){recordBattleLog(`Guild training: ${recipients.length} inactive adventurer${recipients.length===1?'':'s'} (including room staff) share 20% of the party’s average battle XP each. ${awarded} total XP awarded; fractional XP carries forward. No JP awarded.`);save();renderAll();renderRun()}return result};
const reserveRenderRooms=renderRooms;
renderRooms=function(...args){const result=reserveRenderRooms(...args);let note=document.getElementById('reserveTrainingNote');if(!note){note=document.createElement('p');note.id='reserveTrainingNote';note.className='hint';document.getElementById('rooms')?.after(note)}note.textContent='Guild training: room staff and other inactive members earn 20% of the expedition party’s average battle XP per victory. No JP. Members on job-board assignments are excluded.';return result};
renderRooms();
